import type { ElementType, HTMLAttributes, ReactNode } from 'react'
import { cn } from '@/react/lib/cn'

// The console's type as one part (main.css @theme, console2.css .v2-title, .v2-meta, .v2-mono, .v2-link, Marked.vue).
// title: 20px Faculty Glyphic, a page's title (h1). ui: 13px Geist, the default. strong: 13px medium. meta: 12px muted,
// captions under a field, timestamps. caption: 11px muted, the smallest. code: 13px Geist Mono; code-sm: 12px mono, for
// IDs, keys and namespace names. link: ink text with a quiet underline 4px under it that turns ink on hover. mark: a
// query's word in a passage, medium weight in ink, never a fill. `as` overrides the tag.
export type TextVariant = 'title' | 'ui' | 'strong' | 'meta' | 'caption' | 'code' | 'code-sm' | 'link' | 'mark'

export interface TextProps extends HTMLAttributes<HTMLElement> {
  variant?: TextVariant
  /** The tag, in place of the variant's own. */
  as?: string
  href?: string
  children?: ReactNode
}

const TAGS: Record<TextVariant, string> = { 'title': 'h1', 'ui': 'p', 'strong': 'p', 'meta': 'p', 'caption': 'p', 'code': 'code', 'code-sm': 'code', 'link': 'a', 'mark': 'strong' }
const CLASSES: Record<TextVariant, string> = {
  'title': 'type-heading-3 text-fg',
  'ui': 'type-ui text-fg',
  'strong': 'type-ui-strong text-fg',
  'meta': 'type-meta text-fg-muted',
  'caption': 'type-caption text-fg-muted',
  'code': 'type-code text-fg',
  'code-sm': 'type-code-sm text-fg',
  'link': 'ds-text-link text-fg',
  'mark': 'font-medium text-fg',
}

export function Text({ variant = 'ui', as, href, className, children, ...rest }: TextProps) {
  const tag = as ?? (variant === 'link' && !href ? 'button' : TAGS[variant])
  const Tag = tag as ElementType
  return (
    <>
      <style href="ds-text" precedence="ds">{css}</style>
      <Tag data-ds="text" href={href} type={tag === 'button' ? 'button' : undefined} className={cn(CLASSES[variant], className)} {...rest}>{children}</Tag>
    </>
  )
}

export default Text

const css = `
.ds-text-link { cursor: pointer; text-decoration: underline; text-decoration-color: var(--ds-color-edge-strong); text-underline-offset: 4px; transition: text-decoration-color var(--ds-duration-enter) var(--ds-easing-standard); }
@media (hover: hover) and (pointer: fine) { .ds-text-link:hover { text-decoration-color: var(--ds-color-fg); } }
`

// Joins class names, skipping falsy ones: cn('a', on && 'b', ['c', undefined]). It does not merge conflicting
// utilities (no tailwind-merge), as Vue's class binding does not: the library's classes are written not to compete,
// and a className from the caller is appended after them, as Vue appends a fallthrough class.
export type ClassValue = string | false | null | undefined | 0 | ClassValue[]

export function cn(...values: ClassValue[]): string {
	const out: string[] = []
	for (const v of values) {
		if (!v) continue
		if (Array.isArray(v)) {
			const s = cn(...v)
			if (s) out.push(s)
		}
		else out.push(v)
	}
	return out.join(' ')
}

import { html, type PropertyValues } from 'lit'
import { DsElement, define } from '@/elements/lib/element'
import styles from 'virtual:tw'

// Text.vue as <conare-text>: the console's type as one part (main.css @theme, console2.css .v2-title, .v2-meta,
// .v2-mono, .v2-link, Marked.vue). title: 20px Faculty Glyphic, a page's title (a level 1 heading). ui: 13px Geist, the
// default. strong: 13px medium. meta: 12px muted, captions under a field, timestamps. caption: 11px muted, the
// smallest. code: 13px Geist Mono; code-sm: 12px mono, for IDs, keys and namespace names. link: ink text with a quiet
// underline 4px under it that turns ink on hover. mark: a query's word in a passage, medium weight in ink, never a fill.
//
// The host is the text's box (text.css), so a class on <conare-text> (a margin, a width) lands on it as a class on
// <Text> does, and it takes the role of the variant's tag (heading, paragraph, code, strong). Its variant's colour and
// type are !important, so they hold over the page's scoped base in apps that only add components; set another through
// --type-color, --type-size or --type-leading on the element (class="[--type-color:...]"). A link is a real <a> (or a
// <button> without `href`) inside, the host staying out of the way. `as` names another tag for its role.
export type TextVariant = 'title' | 'ui' | 'strong' | 'meta' | 'caption' | 'code' | 'code-sm' | 'link' | 'mark'

const TAGS: Record<TextVariant, string> = { 'title': 'h1', 'ui': 'p', 'strong': 'p', 'meta': 'p', 'caption': 'p', 'code': 'code', 'code-sm': 'code', 'link': 'a', 'mark': 'strong' }
// The role each tag has, set on the host through ElementInternals.
const ROLES: Record<string, [string | null, string | null]> = {
	h1: ['heading', '1'], h2: ['heading', '2'], h3: ['heading', '3'], h4: ['heading', '4'], p: ['paragraph', null], code: ['code', null],
	strong: ['strong', null], em: ['emphasis', null], span: [null, null], div: [null, null], li: ['listitem', null], label: [null, null],
}
// Tags that sit in the line, as their own display: inline does.
const INLINE = new Set(['code', 'strong', 'em', 'span', 'label', 'a', 'button'])

/**
 * @summary The console's type as one part.
 * @slot - The text.
 * @cssprop --type-color - The colour, in place of the variant's (a class like text-fg-soft does not reach it).
 * @cssprop --type-size - The font size, in place of the variant's.
 * @cssprop --type-leading - The line height, in place of the variant's.
 */
export class Text extends DsElement {
	static styles = [DsElement.styles, styles]
	static properties = { variant: { reflect: true }, as: {}, href: {} }

	variant: TextVariant = 'ui'
	/** The tag whose role it takes, in place of the variant's own. */
	as?: string
	/** On `link`: where it goes (without it, a button). */
	href?: string
	private internals = this.attachInternals()

	get tag() {
		return this.as ?? (this.variant === 'link' && !this.href ? 'button' : TAGS[this.variant] ?? 'p')
	}

	protected willUpdate(changed: PropertyValues) {
		super.willUpdate(changed)
		const tag = this.tag
		const box = tag !== 'a' && tag !== 'button'
		const [role, level] = box ? ROLES[tag] ?? [null, null] : [null, null]
		this.internals.role = role
		this.internals.ariaLevel = level
		this.toggleAttribute('data-inline', box && INLINE.has(tag))
		this.toggleAttribute('data-control', !box)
	}

	render() {
		const tag = this.tag
		if (tag === 'a') return html`<a data-ds="text" href=${this.href ?? ''} class="ds-text-link text-fg"><slot></slot></a>`
		if (tag === 'button') return html`<button data-ds="text" type="button" class="ds-text-link text-fg"><slot></slot></button>`
		return html`<slot></slot>`
	}
}

define('text', Text)

/* The host is the text's box (Text.vue's root). Its variant's look is !important, so it holds over the page's scoped
   [data-ds] base in apps that only add components (Vue's utilities on the root beat that base; a :host rule would not).
   A page sets another colour, size or line height through --type-color, --type-size and --type-leading on the
   element (they don't inherit, so text inside keeps its own variant); any other class on the
   host (a margin, a width) lands as one on <Text> does. */
@property --type-color { syntax: "*"; inherits: false; }
@property --type-size { syntax: "*"; inherits: false; }
@property --type-leading { syntax: "*"; inherits: false; }
:host {
  display: block;
  color: var(--type-color, var(--_color)) !important;
}
:host(:not([variant="mark"])) {
  font-family: var(--ds-font-text) !important;
  font-size: var(--type-size, var(--_size)) !important;
  line-height: var(--type-leading, var(--_leading)) !important;
  font-weight: var(--_weight);
  letter-spacing: var(--_tracking);
}
:host([data-inline]) { display: inline; }
/* A link or button draws its own box inside. */
:host([data-control]) { display: contents; }
/* Each variant's type (type-* in the theme) and colour. */
:host { --_color: var(--ds-color-fg); --_size: var(--ds-text-ui); --_leading: var(--ds-text-ui-leading); --_weight: var(--ds-font-weight-regular); --_tracking: 0; }
:host([variant="title"]) { font-family: var(--ds-font-heading) !important; --_size: var(--ds-text-heading-3); --_leading: var(--ds-text-heading-3-leading); }
:host([variant="strong"]) { --_weight: var(--ds-font-weight-medium); }
:host([variant="meta"]) { --_color: var(--ds-color-fg-muted); --_size: var(--ds-text-meta); --_leading: var(--ds-text-meta-leading); }
:host([variant="caption"]) { --_color: var(--ds-color-fg-muted); --_size: var(--ds-text-caption); --_leading: var(--ds-text-caption-leading); }
:host([variant="code"]) { font-family: var(--ds-font-code) !important; }
:host([variant="code-sm"]) { font-family: var(--ds-font-code) !important; --_size: var(--ds-text-meta); --_leading: var(--ds-text-meta-leading); }
/* mark sets only weight and colour (font-medium text-fg), as in Vue: its type is the passage's (or the base's). */
:host([variant="mark"]) { font-weight: var(--ds-font-weight-medium); }
/* Text.vue's <style>, as it is. */
.ds-text-link { cursor: pointer; text-decoration: underline; text-decoration-color: var(--ds-color-edge-strong); text-underline-offset: 4px; transition: text-decoration-color var(--ds-duration-enter) var(--ds-easing-standard); }
@media (hover: hover) and (pointer: fine) { .ds-text-link:hover { text-decoration-color: var(--ds-color-fg); } }
